          return Err(KernelError::PreconditionViolation(
              format!("{child} is not a direct child of {parent}"),
          ));
      }
      if state.agent_active.contains(&parent) {
          return Err(KernelError::PreconditionViolation(
              format!("parent {parent} is still active (use revoke, not cascade_revoke)"),
